const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define study area: east of Nile River in Cairo
  const cairoPoint = ee.Geometry.Point([31.35, 30.05]);
  const geometry = cairoPoint.buffer(15000); // ~15 km buffer

  // Define time periods
  const date1Start = '1984-07-01';
  const date1End = '1984-07-31';
  const date2Start = '2019-09-01';
  const date2End = '2019-09-30';

  // Function to mask clouds in Landsat 5 TM
  function maskCloudsLandsat5(image) {
    const qa = image.select('QA');
    const cloud = qa.bitwiseAnd(1 << 4).eq(0);
    return image.updateMask(cloud);
  }

  // Function to mask clouds in Landsat 8 OLI
  function maskCloudsLandsat8(image) {
    const qa = image.select('QA_PIXEL');
    const cloud = qa.bitwiseAnd(1 << 3).eq(0).and(qa.bitwiseAnd(1 << 4).eq(0));
    return image.updateMask(cloud);
  }

  // Function to calculate NDBI (Normalized Difference Built-up Index)
  function calcNDBI(image) {
    const ndbi = image.normalizedDifference(['SWIR1', 'NIR']);
    return ndbi.rename('NDBI');
  }

  // Acquire Landsat 5 TM for July 1984
  let col1984 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate(date1Start, date1End)
    .map(maskCloudsLandsat5);

  const size1984 = col1984.size().getInfo();
  print('1984 July Images Found: ' + size1984);

  if (size1984 === 0) {
    print('No images available for July 1984.');
    print('C1');
    return;
  }

  // Calculate NDBI for 1984
  const ndbi1984 = col1984.map(calcNDBI).mean();
  const count1984 = ndbi1984.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  print('1984 Valid Pixels: ' + count1984);

  if (count1984 === 0 || count1984 === null) {
    print('No valid pixels after cloud masking in 1984.');
    print('C2');
    return;
  }

  const mean1984 = ndbi1984.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  // Acquire Landsat 8 OLI for September 2019
  let col2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(geometry)
    .filterDate(date2Start, date2End)
    .map(maskCloudsLandsat8);

  const size2019 = col2019.size().getInfo();
  print('2019 September Images Found: ' + size2019);

  if (size2019 === 0) {
    print('No images available for September 2019.');
    print('C1');
    return;
  }

  // Calculate NDBI for 2019
  const ndbi2019 = col2019.map(calcNDBI).mean();
  const count2019 = ndbi2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  print('2019 Valid Pixels: ' + count2019);

  if (count2019 === 0 || count2019 === null) {
    print('No valid pixels after cloud masking in 2019.');
    print('C2');
    return;
  }

  const mean2019 = ndbi2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geometry,
    scale: 30,
    maxPixels: 1e9
  }).get('NDBI').getInfo();

  // Validation
  print('1984 Mean NDBI: ' + (mean1984 !== null ? mean1984.toFixed(4) : 'null'));
  print('2019 Mean NDBI: ' + (mean2019 !== null ? mean2019.toFixed(4) : 'null'));

  if (mean1984 === null || mean2019 === null || isNaN(mean1984) || isNaN(mean2019)) {
    print('C3');
    return;
  }

  // Check if NDBI values are within valid range
  if (mean1984 < -1 || mean1984 > 1 || mean2019 < -1 || mean2019 > 1) {
    print('C3');
    return;
  }

  const difference = mean2019 - mean1984;
  print('NDBI Increase: ' + difference.toFixed(4));

  if (mean2019 > mean1984) {
    print('A');
  } else {
    print('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
